import { REGION_LABELS, REGION_COUNTRY } from "@/lib/node-regions";
import { APP } from "@/lib/nx/sprites";
import { GAME_ART_SLUG, type GameFamily } from "@/lib/games";

/* Presentation data for the deploy wizard.
 *
 * The rule this file exists to enforce: NOTHING PRICED LIVES HERE. The design
 * sandbox kept plans, add-on rates and term discounts in a catalog like this and
 * did the arithmetic in the browser. In the real system every one of those
 * numbers has an owner — Plan/GamePlan/HostingPlan/EmailPlan rows, and
 * `orderQuote` for anything derived — and a second copy here would be a second
 * pricing formula that silently drifts from the one that charges the card.
 *
 * What IS allowed here is data that has no source anywhere else and cannot be
 * wrong in a way that costs money: where a datacentre sits on a globe, which
 * artwork a service tile uses, how far a disk slider steps.
 */

/** Formatting only. Cents in, string out; no arithmetic beyond the divide. */
export const money = (cents: number) =>
  "$" + (cents / 100).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

export type Region = {
  key: string;
  name: string;
  area: string;
  flag: string;
  /** Degrees, for the orthographic globe in the region step. */
  lat: number;
  lon: number;
  /**
   * The enabled nodes sitting in this region. The order intent wants a specific
   * `nodeId`, but the design asks the customer for a REGION — so the wizard
   * resolves one from here. Without this the intent would carry no node and the
   * platform's scheduler would place the server on RAM headroom alone, silently
   * ignoring the location the customer just chose.
   */
  nodeIds: string[];
  /**
   * NOMINAL round-trip, milliseconds. This is an indicative figure for the
   * region, NOT a measurement of the customer's own connection — nothing on the
   * platform probes latency per visitor. It exists so the picker can rank
   * locations sensibly; it must never be presented as "your" latency.
   */
  ms: number;
};

/* Keyed by the platform's REAL datacentre codes (lib/node-regions.ts), not an
   invented set — the wizard offers a region only where a Node actually exists,
   so the picker can never sell a location we cannot provision in. Coordinates
   are the only thing added here; the labels and flags come from the shared map
   so this file cannot drift from it. */
const COORDS: Record<string, { lat: number; lon: number; area: string; ms: number }> = {
  sgp1: { lat: 1.35, lon: 103.82, area: "Asia", ms: 12 },
  bhs1: { lat: 45.31, lon: -73.87, area: "North America", ms: 62 },
  gra1: { lat: 50.99, lon: 2.13, area: "Europe", ms: 68 },
  rbx1: { lat: 50.69, lon: 3.17, area: "Europe", ms: 68 },
  waw1: { lat: 52.23, lon: 21.01, area: "Europe", ms: 74 },
  fsn1: { lat: 50.48, lon: 12.34, area: "Europe", ms: 70 },
  nbg1: { lat: 49.45, lon: 11.08, area: "Europe", ms: 70 },
  hel1: { lat: 60.17, lon: 24.94, area: "Europe", ms: 76 },
  ash1: { lat: 39.04, lon: -77.49, area: "North America", ms: 52 },
  hil1: { lat: 45.52, lon: -122.98, area: "North America", ms: 48 },
};

/** Build the picker's region list from the nodes that actually exist. */
export function regionsFrom(nodes: { id: string; region: string }[]): Region[] {
  const byRegion = new Map<string, string[]>();
  for (const n of nodes) {
    if (!COORDS[n.region]) continue; // no coordinates -> cannot be drawn, so not offered
    const list = byRegion.get(n.region) ?? [];
    list.push(n.id);
    byRegion.set(n.region, list);
  }
  return [...byRegion.entries()].map(([code, nodeIds]) => {
    const c = COORDS[code];
    return {
      key: code,
      name: REGION_LABELS[code] ?? code,
      area: c.area,
      flag: REGION_COUNTRY[code] ?? "sg",
      lat: c.lat,
      lon: c.lon,
      ms: c.ms,
      nodeIds,
    };
  });
}

/** Which service tiles the first step offers, and the artwork each uses. */
/* Substituted at render time with the number of game families that actually
   have an active plan. It was the literal string "41 supported games", carried
   over from the design fixtures — wrong in every environment that is not
   exactly 41 games wide, and silently wrong again the day a game is added or
   retired. The deploy wizard swaps it for a real count. */
export const GAMES_COUNT_BULLET = "__GAMES_COUNT__ supported games";

export const SERVICE_TILES = [
  { key: "vps", name: "VPS Servers", icon: "vps", tagline: "Full control. Maximum performance.", unit: "/mo",
    bullets: ["Dedicated resources", "Full root access", "Install anything", "Scalable at any time"] },
  { key: "game", name: "Game Servers", icon: "game", tagline: "Lag less. Play more.", unit: "/mo",
    bullets: ["Instant deployment", GAMES_COUNT_BULLET, "DDoS protection", "Easy mod support"] },
  { key: "hosting", name: "Cloud Hosting", icon: "hosting", tagline: "Simple. Reliable. Affordable.", unit: "/mo",
    bullets: ["Web hosting", "One-click installs", "Free SSL certificates", "Perfect for websites & apps"] },
  { key: "email", name: "Business Email", icon: "email", tagline: "Your domain. Your inbox.", unit: "/mo",
    bullets: ["Mail on your own domain", "Webmail + IMAP", "Spam & virus filtering", "Calendar and contacts"] },
  { key: "domains", name: "Domains", icon: "domains", tagline: "Claim your name.", unit: "/yr",
    bullets: ["400+ extensions", "Free WHOIS privacy", "Free inbox included", "Managed DNS"] },
] as const;

export type ServiceKey = (typeof SERVICE_TILES)[number]["key"];

/* Slider geometry only. The PRICE per GB is not here — it comes from
   `extraDiskPerGbCents()`, the same function the charge path reads. */
export const DISK_STEP = { step: 10, min: 0, max: 500 };


/* ── third-party marks ────────────────────────────────────────────────────
   Control panels and applications have their own drawn marks in the app sprite
   sheet; the interface icon set has no cPanel or WordPress glyph, so falling
   back to it renders every one of them as the same generic cube.

   Template names carry qualifiers the sheet's keys do not — "Caddy (auto-SSL)",
   "WireGuard VPN", "Uptime Kuma (monitoring)" — so match progressively rather
   than demanding an exact string. */
export function appSpriteKey(name: string): string | null {
  if (APP[name]) return name;
  // drop a parenthetical: "Pi-hole (ad blocker)" -> "Pi-hole"
  const bare = name.replace(/\s*\(.*\)\s*$/, "").trim();
  if (APP[bare]) return bare;
  // longest key that the name starts with: "WireGuard VPN" -> "WireGuard"
  let best: string | null = null;
  for (const k of Object.keys(APP)) {
    if (bare.toLowerCase().startsWith(k.toLowerCase()) && (!best || k.length > best.length)) best = k;
  }
  return best;
}

/* ── game art ─────────────────────────────────────────────────────────────
   Used to be its own 18-entry map pointing at /nx/games/<slug>.webp — a
   second, much smaller art catalogue than the real one, left over from
   before the 2026-09-13 "Game heros and covers" board card filled in art
   for every family. That's why this grid kept showing the generic
   controller icon for titles (Barotrauma, Eco, Killing Floor 2, Sandstorm,
   Mordhau, Squad, and most others) that already had real key-art rendering
   fine on GameCoverTile/GameHero elsewhere in the portal: two art sources
   that only one of them ever got updated.

   Now the same single source of truth as everywhere else: GAME_ART_SLUG in
   lib/games.ts, resolved to the real file at public/games/art/<slug>_hero.jpg.
   `.hero` (landscape) rather than `.poster` (portrait) because this grid's
   tiles are landscape (aspect-[16/11]) — a poster's vertical title lockup
   would crop badly at that ratio. A family outside the registry (or whose
   hero file genuinely doesn't exist, e.g. the deliberately-unlaunched
   Plutonium variants) still just falls back to the service mark below. */
export function gameArt(family: string): string | null {
  const slug = GAME_ART_SLUG[family?.toLowerCase() as GameFamily]?.hero;
  return slug ? `/games/art/${slug}_hero.jpg` : null;
}

