import { db } from "../lib/db";

async function main() {
  const plans = await db.gamePlan.findMany({
    where: { active: true },
    select: { gameFamily: true, name: true, ramMB: true, slots: true, priceCents: true, introPriceCents: true, sortOrder: true, cpuCores: true, diskGB: true },
    orderBy: [{ gameFamily: "asc" }, { sortOrder: "asc" }],
  });
  const byFamily = new Map<string, typeof plans>();
  for (const p of plans) {
    const list = byFamily.get(p.gameFamily) ?? [];
    list.push(p);
    byFamily.set(p.gameFamily, list);
  }
  const families = [...byFamily.keys()].sort();
  console.log("ACTIVE_FAMILIES_COUNT", families.length);
  console.log("ACTIVE_FAMILIES", JSON.stringify(families));
  for (const f of families) {
    const list = byFamily.get(f)!;
    const cheapest = list.reduce((a, b) => (( (b.introPriceCents ?? b.priceCents) < (a.introPriceCents ?? a.priceCents)) ? b : a));
    console.log(f, "plans=" + list.length, "cheapest=" + JSON.stringify(cheapest));
  }
  process.exit(0);
}
main().catch((e) => { console.error(e); process.exit(1); });

