44	export function PricingGrid({ plans, annualPct = 0 }: { plans: PlanCard[]; annualPct?: number }) {
45	  // Prices are USD-cents in the DB; `money` converts them to the visitor's display
46	  // currency (geo/manual) for rendering only — checkout still charges the USD amount.
47	  const money = useDisplayMoney();
48	  // Billing toggle — Annual is on by default when it's a real discount, so the
49	  // headline price shows the better-value figure first. Switching to Monthly shows
50	  // the undiscounted monthly price. Every figure is DB-fed through termPriceCents,
51	  // the SAME formula checkout charges — displayed === charged.
52	  const annualAvailable = annualPct > 0;
53	  const [annual, setAnnual] = useState(true);
54	  const showAnnual = annual && annualAvailable;
