import Link from "next/link";
import type { Metadata } from "next";
import { GameLandingCombined } from "@/components/marketing/gamelanding/GameLandingCombined";
import { PREVIEW_GAMES } from "@/components/marketing/gamelanding/data";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";

/**
 * LIVE — flagship "Combined" game-landing design, piloted here first.
 *
 * Real pricing/metadata/JSON-LD are unchanged from the previous hand-rolled
 * version of this page. The plan figures already matched the PREVIEW_GAMES.rust
 * demo data exactly (4GB $12.99/40 slots, 6GB $17.99/60 slots popular, 10GB
 * $29.99/150 slots), so no price override was needed here — see
 * palworld-server-hosting/page.tsx for an example where a real price differed
 * from the preview data and had to be corrected.
 *
 * The FAQ + related-links sections below the flagship template are carried
 * over verbatim from the previous page (same copy, same JSON-LD) since
 * GameLandingCombined doesn't render its own FAQ/related sections.
 */

export const metadata: Metadata = {
  title: "Rust Server Hosting — Modded & Vanilla, Instant Setup",
  description:
    "Managed Rust server hosting from $12.99/mo. One-click mods and plugins, full FTP, and instant setup on a low-latency Singapore network. Scale players anytime.",
  alternates: { canonical: "/rust-server-hosting" },
  openGraph: {
    type: "article",
    title: "Rust Server Hosting — Modded & Vanilla, Instant Setup",
    description:
      "Managed Rust hosting: one-click mods and plugins, full FTP, and instant setup on a low-latency Singapore network. From $12.99/mo.",
    url: `${APP_URL}/rust-server-hosting`,
  },
};

const GAME = PREVIEW_GAMES.rust;

const FAQ = [
  {
    q: "Is this a managed game server or a VPS I set up myself?",
    a: "It's a fully managed Rust server. Unlike our VPS plans, there's no operating system to install or maintain — you order a plan, choose vanilla or modded, and the server is provisioned and online in minutes. You manage it from a game panel with one-click mods, plugins, and full FTP.",
  },
  {
    q: "Which plan do I need?",
    a: "The 4 GB / 40-slot plan at $12.99 suits a vanilla or lightly-modded wipe for a small group. The 6 GB / 60-slot plan at $17.99 is our popular pick for active modded servers. Choose the 10 GB / 150-slot plan at $29.99 for big community wipes with heavy plugins. Rust is RAM-hungry, so size up if you run a large map or many plugins — you can scale any time.",
  },
  {
    q: "Can I run a modded server with Oxide/uMod plugins?",
    a: "Yes. You can enable Oxide/uMod and install popular plugins — kits, clans, teleport, economy, and more — in one click from the panel, or upload your own over FTP. You can also run a pure vanilla server if you prefer.",
  },
  {
    q: "Can I upload a custom map and edit configs?",
    a: "Absolutely. Full FTP access lets you upload custom maps, drop in plugins, and hand-edit server.cfg or any plugin config file, so you have complete control over how your wipe plays.",
  },
  {
    q: "How quickly is my server ready?",
    a: "Setup is instant — your Rust server is provisioned and online within minutes of ordering, so you can set your map, schedule the wipe, and share the connect string right away.",
  },
];

const RELATED = [
  { label: "All game servers", href: "/game-servers" },
  { label: "Minecraft server hosting", href: "/minecraft-server-hosting" },
  { label: "VPS hosting", href: "/vps" },
  { label: "Pricing", href: "/pricing" },
];

export default function RustServerHostingPage() {
  return (
    <>
      <FaqJsonLd items={FAQ} />
      <ProductOffersJsonLd
        name="Nxeon Rust Server Hosting"
        description={GAME.deck}
        url={`${APP_URL}/game-servers`}
        offers={GAME.plans.map((p) => ({
          name: `${GAME.name} ${p.tier} (${p.ram})`,
          price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
        }))}
      />

      <GameLandingCombined game={GAME} reviewBadges={<ReviewBadges />} />

      {/* FAQ */}
      <Section tone="base" size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-3">
          {FAQ.map((f) => (
            <details key={f.q} className="card group">
              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
                <span className="flex items-center justify-between gap-4">
                  {f.q}
                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
                </span>
              </summary>
              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
            </details>
          ))}
        </div>
      </Section>

      {/* Related */}
      <Section tone="base" size="sm">
        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
          {RELATED.map((r) => (
            <Link
              key={r.href}
              href={r.href}
              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
            >
              {r.label}
            </Link>
          ))}
        </div>
      </Section>
    </>
  );
}

