import { useDisplayMoney } from "@/components/currency/CurrencyContext";
import { deployHref, type DeployService } from "@/lib/deploy-intent";

export type PlanCard = {
  id: string;
  name: string;
  cpuCores: number;
  ramMB: number;
  diskGB: number;
  bandwidthTB: number;
  priceCents: number;
  storageTier: string;
  /**
   * LOW introductory MONTHLY price (cents) for the first term — the plan
   * RENEWS at `priceCents`. Optional: most callers pass a raw `db.plan` row
   * straight through (it carries `introPriceCents` at runtime even though this
   * narrower display type doesn't declare it), in which case `planIntroMonthlyCents`
   * reads it directly and this field is never needed. Set it explicitly only when
   * the caller built a plain object that dropped the original DB row.
   */
  introMonthlyCents?: number | null;
  /**
   * Player-slot count — GamePlan rows only (a `db.gamePlan` row mapped to this
   * shape by its caller). Shown as a headline feature instead of the generic
   * vCPU/RAM/disk framing when `service="game"`, since "slots" is the number a
   * game-hosting shopper actually cares about.
   */
  slots?: number | null;
};

function planFeatures(p: PlanCard, service: DeployService): string[] {
  const disk = p.storageTier === "hdd" ? "HDD storage" : "NVMe SSD storage";
  const isGame = service === "game";
  return [
    ...(isGame && p.slots ? [`${p.slots} player slots`] : []),
    `${p.cpuCores} vCPU core${p.cpuCores > 1 ? "s" : ""}`,
    `${(p.ramMB / 1024).toFixed(p.ramMB % 1024 ? 1 : 0)} GB RAM`,
    `${p.diskGB} GB ${disk}`,
    `${p.bandwidthTB} TB bandwidth`,
    isGame ? "Full file access (FTP)" : "Full root access",
    "Free DDoS protection",
  ];
}

