import type { Metadata } from "next";
import { notFound } from "next/navigation";
import { db } from "@/lib/db";
import { UseCaseLanding } from "@/components/marketing/UseCaseLanding";
import type { PlanCard } from "@/components/marketing/PricingGrid";
import { APP_URL } from "@/components/marketing/StructuredData";
import {
  findCombo,
  buildLanding,
  findRegionCombo,
  buildRegionLanding,
  LANDING_SLUGS,
  REGION_LANDING_SLUGS,
  type LandingPlan,
  type BuiltLanding,
} from "@/lib/marketing/locationLandings";
import {
  findGameLocationCombo,
  buildGameLocationLanding,
  findGeneralLocationCombo,
  buildGeneralLocationLanding,
  GAME_LOCATION_SLUGS,
  GENERAL_LOCATION_SLUGS,
  type GamePlanRow,
} from "@/lib/marketing/gameLocationLandings";

/**
 * Programmatic "(location) (service)" marketing landing pages, the region-tier
 * umbrella pages above them, AND (added here) the game-family × location
 * matrix + the general per-location VPS/Game-Server pages that don't already
 * exist via the tables above — see lib/marketing/gameLocationLandings.ts's
 * file doc for the full architecture note.
 *
 * Four data tables, one route: a slug is checked against the region matrix,
 * then the city matrix, then the game×location matrix, then the general
 * new-location matrix — in that order, so nothing here can ever shadow a
 * hand-written static marketing page (which wins at request time anyway) or
 * silently collide with an existing slug. Anything in none of the four falls
 * through to a 404. Real DB rows (VPS `Plan` or, for a game×location combo,
 * that family's real `GamePlan` rows) feed every page's pricing grid and
 * Product rich-result — nothing here is a hardcoded price.
 */

export const dynamic = "force-dynamic";

// Pre-declare every known slug across all four tables so Next can enumerate
// them at build time; unknown slugs are rejected in the page/metadata via
// notFound().
export function generateStaticParams(): Array<{ slug: string }> {
  return [...REGION_LANDING_SLUGS, ...LANDING_SLUGS, ...GAME_LOCATION_SLUGS, ...GENERAL_LOCATION_SLUGS].map((slug) => ({
    slug,
  }));
}

async function loadVpsPlans(): Promise<LandingPlan[]> {
  return db.plan.findMany({
    where: { active: true },
    orderBy: { sortOrder: "asc" },
  });
}

/**
 * Real, active `GamePlan` rows for one family, mapped both to the plain
 * `GamePlanRow[]` the copy builder reads for prose (RAM/slots/price only)
 * and to full `PlanCard[]` for the pricing grid — `bandwidthTB`/`storageTier`
 * come from each row's real `basePlan` (the actual VPS-grade Plan the game
 * server is provisioned on), never a fabricated number.
 */
async function loadGamePlans(gameFamily: string): Promise<{ rows: GamePlanRow[]; cards: PlanCard[] }> {
  const plans = await db.gamePlan.findMany({
    where: { gameFamily, active: true },
    orderBy: { sortOrder: "asc" },
    include: { basePlan: true },
  });
  const rows: GamePlanRow[] = plans.map((p) => ({
    id: p.id,
    name: p.name,
    ramMB: p.ramMB,
    slots: p.slots,
    priceCents: p.priceCents,
    introPriceCents: p.introPriceCents,
  }));
  const cards: PlanCard[] = plans.map((p) => ({
    id: p.id,
    name: p.name,
    cpuCores: p.cpuCores,
    ramMB: p.ramMB,
    diskGB: p.diskGB,
    bandwidthTB: p.basePlan.bandwidthTB,
    priceCents: p.priceCents,
    storageTier: p.basePlan.storageTier,
    introMonthlyCents: p.introPriceCents,
    slots: p.slots,
  }));
  return { rows, cards };
}

type Resolved =
  | { service: "vps" | "web" | "dedicated" | "forex" | "reseller"; built: BuiltLanding; plans: LandingPlan[] }
  | { service: "game"; built: BuiltLanding & { gameFamily?: string; productName?: string }; plans: LandingPlan[] | PlanCard[]; gameFamily?: string; productName?: string };

async function resolve(slug: string): Promise<Resolved | undefined> {
  const regionCombo = findRegionCombo(slug);
  if (regionCombo) {
    const plans = await loadVpsPlans();
    return { service: regionCombo.service.key, built: buildRegionLanding(regionCombo, plans), plans };
  }

  const combo = findCombo(slug);
  if (combo) {
    const plans = await loadVpsPlans();
    return { service: combo.service.key, built: buildLanding(combo, plans), plans };
  }

  const generalCombo = findGeneralLocationCombo(slug);
  if (generalCombo) {
    const plans = await loadVpsPlans();
    return { service: generalCombo.service, built: buildGeneralLocationLanding(generalCombo, plans), plans };
  }

  const gameCombo = findGameLocationCombo(slug);
  if (gameCombo) {
    const { rows, cards } = await loadGamePlans(gameCombo.family);
    const built = buildGameLocationLanding(gameCombo, rows);
    return { service: "game", built, plans: cards, gameFamily: built.gameFamily, productName: built.productName };
  }

  return undefined;
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> {
  const { slug } = await params;
  const resolved = await resolve(slug);
  if (!resolved) return {};
  const { built } = resolved;

  const url = `${APP_URL}/${slug}`;

  return {
    title: built.metaTitle,
    description: built.metaDescription,
    alternates: { canonical: `/${slug}` },
    openGraph: {
      type: "article",
      title: built.ogTitle,
      description: built.ogDescription,
      url,
    },
    twitter: {
      card: "summary_large_image",
      title: built.ogTitle,
      description: built.ogDescription,
    },
  };
}

export default async function LocationServiceLandingPage({
  params,
}: {
  params: Promise<{ slug: string }>;
}) {
  const { slug } = await params;
  const resolved = await resolve(slug);
  if (!resolved) notFound();
  const { built, plans } = resolved;

  const url = `${APP_URL}/${slug}`;

  // BreadcrumbList — helps Google render the Home › <Page> trail and reinforces
  // the page's place in the site. FAQ + Product JSON-LD are emitted by
  // UseCaseLanding from the same content, so all three rich results are covered.
  const breadcrumb = {
    "@context": "https://schema.org",
    "@type": "BreadcrumbList",
    itemListElement: [
      { "@type": "ListItem", position: 1, name: "Home", item: APP_URL },
      { "@type": "ListItem", position: 2, name: built.breadcrumbName, item: url },
    ],
  };

  return (
    <>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{ __html: JSON.stringify(breadcrumb) }}
      />
      <UseCaseLanding
        content={built.content}
        plans={plans as PlanCard[]}
        service={resolved.service === "game" ? "game" : "vps"}
        gameFamily={resolved.service === "game" ? resolved.gameFamily : undefined}
        productName={resolved.service === "game" ? resolved.productName : undefined}
        pageUrl={url}
      />
    </>
  );
}

