import { LANDING_SLUGS, REGION_LANDING_SLUGS, RESERVED_SLUGS } from "../lib/marketing/locationLandings";
import { GAME_LOCATION_SLUGS, GENERAL_LOCATION_SLUGS, GAME_LOCATIONS, ACTIVE_GAME_FAMILIES, GAME_LOCATION_COMBOS, GENERAL_LOCATION_COMBOS } from "../lib/marketing/gameLocationLandings";
import fs from "node:fs";
import path from "node:path";

const marketingDir = path.join(__dirname, "..", "app", "(marketing)");
const staticFolders = fs.readdirSync(marketingDir, { withFileTypes: true })
  .filter((d) => d.isDirectory())
  .map((d) => d.name);

const all = [
  ...LANDING_SLUGS.map((s) => ["LANDING_SLUGS", s]),
  ...REGION_LANDING_SLUGS.map((s) => ["REGION_LANDING_SLUGS", s]),
  ...[...RESERVED_SLUGS].map((s) => ["RESERVED_SLUGS", s]),
  ...staticFolders.map((s) => ["staticFolder", s]),
  ...GAME_LOCATION_SLUGS.map((s) => ["GAME_LOCATION_SLUGS", s]),
  ...GENERAL_LOCATION_SLUGS.map((s) => ["GENERAL_LOCATION_SLUGS", s]),
] as [string, string][];

const seen = new Map<string, string>();
let collisions = 0;
for (const [src, slug] of all) {
  if (seen.has(slug) && seen.get(slug) !== src) {
    console.log("COLLISION:", slug, "in", seen.get(slug), "and", src);
    collisions++;
  } else if (!seen.has(slug)) {
    seen.set(slug, src);
  }
}
console.log("Total unique slugs across all tables+static folders:", seen.size);
console.log("Collisions found:", collisions);

console.log("GAME_LOCATIONS count:", GAME_LOCATIONS.length);
console.log("ACTIVE_GAME_FAMILIES count:", ACTIVE_GAME_FAMILIES.length);
console.log("GAME_LOCATION_COMBOS count (expect locations*families):", GAME_LOCATION_COMBOS.length, GAME_LOCATIONS.length * ACTIVE_GAME_FAMILIES.length);
console.log("GENERAL_LOCATION_COMBOS count:", GENERAL_LOCATION_COMBOS.length);
console.log("Sample game-location slugs:", GAME_LOCATION_SLUGS.slice(0, 5));
console.log("Sample general slugs:", GENERAL_LOCATION_SLUGS.slice(0, 6));
console.log("GAME_LOCATIONS slugs:", GAME_LOCATIONS.map(l=>l.slug));

// Duplicate-within-own-table check
const dupCheck = (name: string, arr: string[]) => {
  const s = new Set<string>();
  let dups = 0;
  for (const x of arr) { if (s.has(x)) { dups++; console.log("DUP in", name, x); } s.add(x); }
  console.log(name, "own-duplicates:", dups, "of", arr.length);
};
dupCheck("GAME_LOCATION_SLUGS", GAME_LOCATION_SLUGS);
dupCheck("GENERAL_LOCATION_SLUGS", GENERAL_LOCATION_SLUGS);

